-- 37 Harbour at Night: raises and lowers the tide, turns the fan, and
-- switches the fan's wind and the whirlpool. The floating, the drag of the
-- water, the wind on the boats and on the smoke and the whirlpool's pull are
-- the engine's (`area_effect`). Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/37-harbour-at-night.scene"
local TOP = -60.0
local post_on = nav.post_all_on(SCENE)
local captions = true
local water, surface, fan, wind, pool, status
local t = 0
local fan_on, pool_on = true, false
local spin = 0
local water_y0
local BREEZE = 140

local function refresh()
    if status then
        UI.set_text(status, "fan " .. (fan_on and "on" or "off") .. "   whirlpool " .. (pool_on and "on" or "off"))
    end
end

function init(entity)
    water = Entity.find_by_name("Water")
    surface = Entity.find_by_name("Surface")
    fan = Entity.find_by_name("Fan")
    wind = Entity.find_by_name("Wind")
    pool = Entity.find_by_name("Whirlpool")
    status = Entity.find_by_name("Status")
    if water then
        local _, y = Transform.get_position(water)
        water_y0 = y
    end
    refresh()
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt
    -- The breeze swings from one side to the other over half a minute; the
    -- fan faces it. Only the number changes - the box does the pushing.
    local breeze = math.sin(t * 0.21 + 0.6) * BREEZE
    if wind and fan_on then Area.set(wind, "force", { breeze, 0 }) end
    -- The tide: the water's box moves, and everything floating rides it.
    local tide = math.sin(t * 0.35) * 45
    if water and water_y0 then Transform.set_position(water, 0, water_y0 + tide) end
    if surface then Transform.set_position(surface, math.sin(t * 0.8) * 20, TOP + tide) end
    if Input.is_key_just_pressed("F") then
        fan_on = not fan_on
        if wind then Area.set(wind, "enabled", fan_on) end
        refresh()
    end
    if Input.is_key_just_pressed("W") then
        pool_on = not pool_on
        if pool then Area.set(pool, "enabled", pool_on) end
        refresh()
    end
    if Input.is_key_just_pressed("C") then
        local c = Entity.spawn_prefab("HbCrate")
        Transform.set_position(c, -300 + math.random() * 600, 320)
    end
    if fan then
        spin = spin + dt * (fan_on and (4 + 12 * math.abs(breeze) / BREEZE) or 0)
        Transform.set_rotation(fan, breeze >= 0 and -spin or spin)
    end
end
